        self._callbacks.discard(callback)

    def _add_dependent(self, dependent):
        self._dependents.add(dependent)

    def _recompute(self):
        pass

    def _propagate(self):
        # Recompute all affected cells in dependency order so the system
        # reaches a new stable state, then fire callbacks once per cell,
        # only if the value changed from the previous stable state.
        affected = self._collect_affected()
        ordered = self._topological_order(affected)
        for cell in ordered:
            cell._recompute()
        for cell in ordered:
            if cell._value != cell._previous_value:
                for callback in list(cell._callbacks):
                    callback(cell._value)

    def _collect_affected(self):
        affected = []
        seen = set()
        queue = [self]
        while queue:
            cell = queue.pop()
            for dependent in cell._dependents:
                if dependent not in seen:
                    seen.add(dependent)
                    affected.append(dependent)
                    queue.append(dependent)
        return affected

